-- PostgreSQL starter schema. MVP runtime currently uses in-memory storage.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE app_users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT UNIQUE NOT NULL, full_name TEXT NOT NULL, organization TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('admin','investigator','reviewer')), active BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE cases (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), case_number TEXT UNIQUE NOT NULL, title TEXT NOT NULL, complaint_reference TEXT, investigator_id UUID REFERENCES app_users(id), priority TEXT NOT NULL CHECK (priority IN ('low','medium','high','critical')), status TEXT NOT NULL CHECK (status IN ('open','in_review','escalated','closed')), notes TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE wallets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), network TEXT NOT NULL, address TEXT NOT NULL, first_seen_at TIMESTAMPTZ, UNIQUE(network,address));
CREATE TABLE case_wallets (case_id UUID REFERENCES cases(id) ON DELETE CASCADE, wallet_id UUID REFERENCES wallets(id), PRIMARY KEY(case_id,wallet_id));
CREATE TABLE transactions (tx_hash TEXT NOT NULL, network TEXT NOT NULL, block_number BIGINT, from_address TEXT NOT NULL, to_address TEXT NOT NULL, amount NUMERIC, token TEXT NOT NULL, occurred_at TIMESTAMPTZ, provider TEXT NOT NULL, payload_sha256 TEXT, PRIMARY KEY(network,tx_hash));
CREATE TABLE case_evidence (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), case_id UUID NOT NULL REFERENCES cases(id), evidence_type TEXT NOT NULL, reference TEXT NOT NULL, source TEXT NOT NULL, collected_at TIMESTAMPTZ NOT NULL DEFAULT now(), integrity_sha256 TEXT, collected_by UUID REFERENCES app_users(id), metadata JSONB NOT NULL DEFAULT '{}');
CREATE TABLE audit_events (id BIGSERIAL PRIMARY KEY, actor_id UUID REFERENCES app_users(id), action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), details JSONB NOT NULL DEFAULT '{}');
CREATE INDEX transactions_from_idx ON transactions(network,from_address); CREATE INDEX transactions_to_idx ON transactions(network,to_address); CREATE INDEX evidence_case_idx ON case_evidence(case_id); CREATE INDEX audit_resource_idx ON audit_events(resource_type,resource_id,occurred_at);
